package universalDiscord;

import com.google.inject.Guice;
import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.*;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NotificationFired;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.DrawManager;
import okhttp3.OkHttpClient;
import universalDiscord.message.DiscordMessageHandler;
import universalDiscord.notifiers.*;
import universalDiscord.notifiers.onevent.ChatMessageHandler;
import universalDiscord.notifiers.onevent.WidgetLoadHandler;

import javax.inject.Inject;


@Slf4j
@PluginDescriptor(
        name = "Universal Discord"
)
public class UniversalDiscordPlugin extends Plugin {
    @Inject
    public Client client;
    @Inject
    public OkHttpClient httpClient;
    @Inject
    public DrawManager drawManager;
    @Inject
    public UniversalDiscordConfig config;
    @Inject
    public ItemManager itemManager;

    @Inject
    public ItemSearcher itemSearcher;

    public final DiscordMessageHandler messageHandler = new DiscordMessageHandler(this);
    private final CollectionNotifier collectionNotifier = new CollectionNotifier(this);
    private final PetNotifier petNotifier = new PetNotifier(this);
    private final LevelNotifier levelNotifier = new LevelNotifier(this);
    private final LootNotifier lootNotifier = new LootNotifier(this);
    private final DeathNotifier deathNotifier = new DeathNotifier(this);
    private final SlayerNotifier slayerNotifier = new SlayerNotifier(this);
    private final QuestNotifier questNotifier = new QuestNotifier(this);
    private final ClueNotifier clueNotifier = new ClueNotifier(this);


    @Override
    protected void startUp() {
        Utils.plugin = this;
        itemSearcher.loadItemIdsAndNames();

        log.info("Started up Universal Discord");
    }

    @Override
    protected void shutDown() {
        log.info("Shutting down Universal Discord");
    }

    @Provides
    UniversalDiscordConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(UniversalDiscordConfig.class);
    }

    @Subscribe
    public void onNotificationFired(NotificationFired notif) {

    }

    @Subscribe
    public void onUsernameChanged(UsernameChanged usernameChanged) {
        levelNotifier.reset();
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged gameStateChanged) {
        if (gameStateChanged.getGameState().equals(GameState.LOGIN_SCREEN)) {
            levelNotifier.reset();
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged statChange) {
        levelNotifier.handleLevelUp(statChange.getSkill().getName(), statChange.getLevel());
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        levelNotifier.onTick();
    }

    @Subscribe
    public void onChatMessage(ChatMessage message) {
        ChatMessageType msgType = message.getType();

        if (msgType.equals(ChatMessageType.GAMEMESSAGE)) {
            ChatMessageHandler[] notifiers = new ChatMessageHandler[]{
                    collectionNotifier,
                    petNotifier,
                    slayerNotifier,
                    clueNotifier,
            };
            for (ChatMessageHandler notifier : notifiers) {
                notifier.handleChatMessage(message);
                if (notifier.shouldNotify()) {
                    notifier.handleNotify();
                }
            }
        }
    }

    @Subscribe
    public void onActorDeath(ActorDeath actor) {
        deathNotifier.lastActorDeath = actor;
        if (deathNotifier.shouldNotify()) {
            deathNotifier.handleNotify();
        }
    }

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived npcLootReceived) {
        lootNotifier.handleNpcLootReceived(npcLootReceived);
        if (lootNotifier.shouldNotify()) {
            lootNotifier.handleNotify();
        }
    }

    @Subscribe
    public void onPlayerLootReceived(PlayerLootReceived playerLootReceived) {
        lootNotifier.handlePlayerLootReceived(playerLootReceived);
        if (lootNotifier.shouldNotify()) {
            lootNotifier.handleNotify();
        }
    }

    @Subscribe
    public void onLootReceived(LootReceived lootReceived) {
        lootNotifier.handleLootReceived(lootReceived);
        if (lootNotifier.shouldNotify()) {
            lootNotifier.handleNotify();
        }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event) {
        WidgetLoadHandler[] notifiers = new WidgetLoadHandler[]{
                questNotifier,
                clueNotifier,
        };

        for (WidgetLoadHandler notifier : notifiers) {
            notifier.handleWidgetLoaded(event);
            if (notifier.shouldNotify()) {
                notifier.handleNotify();
            }
        }
    }
}

package universalDiscord;

import net.runelite.api.WorldType;
import net.runelite.client.game.ItemStack;

import javax.annotation.Nullable;
import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

public class Utils {
    public static UniversalDiscordPlugin plugin;

    public static String replaceCommonPlaceholders(String text) {
        String username = getPlayerUrl();
        if (username == null) {
            username = getPlayerName();
        } else {
            username = "[" + getPlayerName() + "](" + getPlayerUrl() + ")";
        }

        return text.replaceAll("%USERNAME%", username);
    }

    public static String getPlayerName() {
        return plugin.client.getLocalPlayer().getName();
    }

    @Nullable
    public static String getPlayerBadgeUrl() {
        String playerBadgeUrl = null;
        if (isSeasonalWorld()) {
            playerBadgeUrl = "https://oldschool.runescape.wiki/images/Leagues_chat_badge.png";
        } else if (isQuestSpeedRunningWorld()) {
            playerBadgeUrl = "https://oldschool.runescape.wiki/images/Speedrunning_World_chat_badge.png";
        } else {
            switch (plugin.client.getAccountType()) {
                case IRONMAN:
                    playerBadgeUrl = "https://oldschool.runescape.wiki/images/Ironman_chat_badge.png";
                    break;
                case HARDCORE_IRONMAN:
                    playerBadgeUrl = "https://oldschool.runescape.wiki/images/Hardcore_ironman_chat_badge.png";
                    break;
                case ULTIMATE_IRONMAN:
                    playerBadgeUrl = "https://oldschool.runescape.wiki/images/Ultimate_ironman_chat_badge.png";
                    break;
                case GROUP_IRONMAN:
                    playerBadgeUrl = "https://oldschool.runescape.wiki/images/Group_ironman_chat_badge.png";
                    break;
                case HARDCORE_GROUP_IRONMAN:
                    playerBadgeUrl = "https://oldschool.runescape.wiki/images/Hardcore_group_ironman_chat_badge.png";
                    break;
            }
        }

        return playerBadgeUrl;
    }

    public static boolean isSeasonalWorld() {
        return plugin.client.getWorldType().contains(WorldType.SEASONAL);
    }

    public static boolean isQuestSpeedRunningWorld() {
        return plugin.client.getWorldType().contains(WorldType.QUEST_SPEEDRUNNING);
    }

    public static String getPlayerUrl() {
        return plugin.config.playerUrlService().playerUrl(getPlayerName());
    }

    public static byte[] convertImageToByteArray(BufferedImage bufferedImage) throws IOException {
        ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
        ImageIO.write(bufferedImage, "png", byteArrayOutputStream);
        return byteArrayOutputStream.toByteArray();
    }

    public static Collection<ItemStack> reduceItemStack(Collection<ItemStack> items) {
        final List<ItemStack> list = new ArrayList<>();

        for (final ItemStack item : items) {
            int quantity = 0;
            for (final ItemStack i : list) {
                if (i.getId() == item.getId()) {
                    quantity = i.getQuantity();
                    list.remove(i);
                    break;
                }
            }

            if (quantity > 0) {
                list.add(new ItemStack(item.getId(), item.getQuantity() + quantity, item.getLocation()));
            } else {
                list.add(item);
            }
        }

        return list;
    }

    public static String getItemImageUrl(int itemId) {
        return "https://static.runelite.net/cache/item/icon/" + itemId + ".png";
    }

    public static String asMarkdownWikiUrl(String search) {
        return asMarkdownWikiUrl(search, search);
    }
    public static String asMarkdownWikiUrl(String search, String linkText) {
        return "[" + linkText + "](" + getWikiUrl(search) + ")";
    }

    public static String getWikiUrl(String search) {
        return "https://oldschool.runescape.wiki/w/Special:Search?search=" + URLEncoder.encode(search, StandardCharsets.UTF_8);
    }
}

